interface InvoicePrinter {
  print(invoice: { id: string }): void;
}

class ConsolePrinter implements InvoicePrinter {
  print(invoice: { id: string }) { console.log(invoice.id); }
}

class NoopPrinter implements InvoicePrinter {
  print(invoice: { id: string }) { /* do nothing */ }
}

function getPrinter(enabled: boolean): InvoicePrinter {
  return enabled ? new ConsolePrinter() : new NoopPrinter();
}

interface DiscountCalculator { calculate(order: any): number }

class StandardCalculator implements DiscountCalculator {
  calculate(order: any) { return 0 }
}

class VipCalculator implements DiscountCalculator {
  calculate(order: any) { return 10 }
}

function getDiscountCalculator(customer?: any): DiscountCalculator | null {
  if (!customer) return null
  if (customer.isVIP) return new VipCalculator()
  return new StandardCalculator()
}

// Callers must do: const calc = getDiscountCalculator(customer); const discount = calc ? calc.calculate(order) : 0

