interface Notifier { notify(message: string): void }
class RealNotifier implements Notifier { notify(m: string) { /* send */ } }
class DefaultNotifier implements Notifier { notify(m: string) { /* no-op */ } }
function getNotifier(enabled: boolean): Notifier { return enabled ? new RealNotifier() : new DefaultNotifier() }

// Version B
function getOptionalNotifier(enabled: boolean): Notifier | null { return enabled ? new RealNotifier() : null }
// callers for Version B must do null checks before calling notify
